// What the code generated by `#[musivum_fakes::fake]` is built from. The macro refers to this
// module by its fixed path, `crate::testutils::fakes`; how a fake is used is written down at
// the macro. Written new for musivum. Only the standard library is used here, and the file
// has no inner attributes or inner doc comments, so that the doc tests of the macro can
// `include!` it.

use std::any::{Any, type_name};
use std::cell::Cell;
use std::fmt;
use std::marker::PhantomData;
use std::ops::Deref;
use std::sync::{Mutex, MutexGuard, PoisonError};

// What the generated code names through this module, to stay short and not to depend on what
// the names mean where a faked trait is.
pub use std::default::Default;
pub use std::marker::{Send, Sync};
pub use std::ops::Fn;
pub use std::sync::Arc;

// ------------------------------------------------
// The fake and the states it is made of

/// A fake of a trait. `FakeTrackSender` is `Fake<FakeTrackSenderState>`: the state has a
/// [`Method`] for every method of the trait and the methods a test configures it with
/// (`write_rtp_returns`, `write_rtp_call_count`, ...), which are reached through `Deref`.
///
/// The fake of a trait with faked supertraits embeds their states in its own, and every
/// faked trait is implemented for all `Fake<F>` whose state has the trait's state in it.
pub struct Fake<F>(F);

impl<F> Fake<F> {
    /// The state of a faked supertrait that is embedded in this fake. Only needed for the
    /// second and later supertraits of a trait: the methods of the first are reached
    /// directly.
    pub fn embedded<S>(&self) -> &S
    where
        F: Has<S>,
    {
        self.0.state()
    }
}

impl<F: Default> Default for Fake<F> {
    fn default() -> Self {
        Fake(F::default())
    }
}

impl<F> Deref for Fake<F> {
    type Target = F;

    fn deref(&self) -> &F {
        &self.0
    }
}

impl<F> fmt::Debug for Fake<F> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = type_name::<F>();
        let name = name.rsplit("::").next().unwrap_or(name);
        f.write_str(name.strip_suffix("State").unwrap_or(name))
    }
}

/// A state that has the state `S` of a faked trait in it: its own, or that of a supertrait.
pub trait Has<S> {
    fn state(&self) -> &S;
}

/// Implemented for `dyn Trait` of every faked trait: names the state of its fake, so that the
/// fake of a subtrait can embed it knowing only the path of the trait.
#[diagnostic::on_unimplemented(
    message = "`{Self}` has no fake that the fake of a subtrait could embed",
    label = "this supertrait has no fake",
    note = "a supertrait of a faked trait has to be marked `#[musivum_fakes::fake]` itself and be dyn-compatible",
    note = "`Send`, `Sync`, `Sized`, `Unpin`, `UnwindSafe`, `RefUnwindSafe`, `Any`, `Debug` and traits written as `std::..`, `core::..` or `alloc::..` are passed over; to pass over others, name the supertraits to embed: `#[fake(extends(TraitA, TraitB))]`"
)]
pub trait Faked {
    type State: Default;
}

/// The state of a fake, from the fake. For the generated code.
pub fn state<S, F: Has<S>>(fake: &Fake<F>) -> &S {
    fake.0.state()
}

/// Go's `x.(*typesfakes.FakeLocalParticipant)`: the fake behind an `Arc<dyn Trait>`, for a
/// trait that has `Any` among its supertraits (`trait LocalParticipant: Any + Send + Sync`;
/// the `Arc<dyn LocalParticipant>` then converts to the argument by itself). Panics if what
/// is behind it is something else.
#[track_caller]
pub fn downcast<T: Any + Send + Sync>(value: Arc<dyn Any + Send + Sync>) -> Arc<T> {
    match value.downcast::<T>() {
        Ok(fake) => fake,
        Err(_) => panic!("this is not a `{}`", type_name::<T>()),
    }
}

// ------------------------------------------------
// Recording arguments

/// What an argument that is not recorded leaves in the arguments of a call: a `&mut`, a
/// `Box<dyn ..>`, a `&dyn ..`, a type that borrows, or a parameter marked `#[fake(skip)]`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct NotRecorded;

/// What an argument has to be for a fake to keep a copy of it.
#[diagnostic::on_unimplemented(
    message = "the fake cannot record an argument of type `{Self}`",
    label = "`{Self}` is not `Clone + Send + 'static`",
    note = "mark the parameter `#[cfg_attr(test, fake(skip))]` (or `#[fake(skip)]` where the macro is not behind `cfg_attr`): it is then left out of the recorded arguments, and a stub still gets it",
    note = "or make the type `Clone`, or pass it in an `Arc`"
)]
pub trait Recorded: Clone + Send + 'static {}

#[diagnostic::do_not_recommend]
impl<T: Clone + Send + 'static> Recorded for T {}

/// The copy of an argument that is recorded: of `T` passed as `&T`.
pub fn rec<T: Recorded>(value: &T) -> T {
    value.clone()
}

/// A `&str` is recorded as a `String`.
pub fn rec_str(value: &str) -> String {
    value.to_owned()
}

/// A `&[T]` is recorded as a `Vec<T>`.
pub fn rec_slice<T: Recorded>(value: &[T]) -> Vec<T> {
    value.to_vec()
}

// ------------------------------------------------
// A method of a fake

/// What gives the value a call returns: a clone of the value a test set, the one value that
/// cannot be cloned, or the closure of `x_returns_with`.
pub type Producer<R> = Arc<dyn Fn() -> R + Send + Sync>;

/// One method of a fake: the calls it got and what a test configured for it. `A` is what is
/// recorded of the arguments of a call, `S` the type of a stub (`dyn Fn(..) -> R + Send +
/// Sync`), `R` what the method returns.
pub struct Method<A, S: ?Sized, R> {
    inner: Mutex<MethodInner<A, S, R>>,
}

struct MethodInner<A, S: ?Sized, R> {
    args_for_call: Vec<A>,
    stub: Option<Arc<S>>,
    returns: Option<Producer<R>>,
    // A list and not a map: there are few of them, and what is here is compiled again for
    // every method of every fake.
    returns_on_call: Vec<(usize, Producer<R>)>,
}

/// What a call to a faked method has to do after it has been recorded.
pub enum Outcome<S: ?Sized, R> {
    /// Call the stub. The lock of the method is not held any more, so the stub may call back
    /// into the fake.
    Stub(Arc<S>),
    /// Return the value that was set for this call, or for all calls.
    Value(R),
    /// Nothing was set: return the zero value.
    Unset,
}

impl<A, S: ?Sized, R> Default for Method<A, S, R> {
    fn default() -> Self {
        Method {
            inner: Mutex::new(MethodInner {
                args_for_call: Vec::new(),
                stub: None,
                returns: None,
                returns_on_call: Vec::new(),
            }),
        }
    }
}

impl<A, S: ?Sized, R> Method<A, S, R> {
    fn lock(&self) -> MutexGuard<'_, MethodInner<A, S, R>> {
        // Nothing of a test runs with the lock held, but be safe against a `Clone` of an
        // argument that panics.
        self.inner.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// A call came in. As in counterfeiter: the call is recorded, then the stub decides if
    /// there is one, else the value for this call, else the value for all calls.
    pub fn call(&self, args: A) -> Outcome<S, R> {
        let producer = {
            let mut inner = self.lock();
            let index = inner.args_for_call.len();
            inner.args_for_call.push(args);
            if let Some(stub) = &inner.stub {
                return Outcome::Stub(Arc::clone(stub));
            }
            let on_call = inner.returns_on_call.iter().find(|(i, _)| *i == index);
            match on_call {
                Some((_, producer)) => Some(Arc::clone(producer)),
                None => inner.returns.clone(),
            }
        };
        // Without the lock: the producer may be a closure of the test.
        match producer {
            Some(producer) => Outcome::Value(producer()),
            None => Outcome::Unset,
        }
    }

    pub fn call_count(&self) -> usize {
        self.lock().args_for_call.len()
    }

    // What these three replace is dropped after the lock is given back: a closure or a value
    // of the test may own anything, a fake too.

    pub fn calls(&self, stub: Arc<S>) {
        let replaced = self.lock().stub.replace(stub);
        drop(replaced);
    }

    pub fn returns(&self, producer: Producer<R>) {
        let replaced = {
            let mut inner = self.lock();
            (inner.stub.take(), inner.returns.replace(producer))
        };
        drop(replaced);
    }

    pub fn returns_on_call(&self, i: usize, producer: Producer<R>) {
        let replaced = {
            let mut inner = self.lock();
            let stub = inner.stub.take();
            let at = inner
                .returns_on_call
                .iter()
                .position(|(index, _)| *index == i);
            match at {
                Some(at) => {
                    let old = std::mem::replace(&mut inner.returns_on_call[at], (i, producer));
                    (stub, Some(old))
                }
                None => {
                    inner.returns_on_call.push((i, producer));
                    (stub, None)
                }
            }
        };
        drop(replaced);
    }
}

// ------------------------------------------------
// The choices that depend on what a type implements
//
// The generated code is not generic, so it can let method resolution choose by the traits a
// concrete type has ("autoref specialisation"): `(&&&x).method()` takes the implementation
// for `&&X` if its bounds hold, else the one for `&X`, else the one for `X`.

/// The arguments of a call, for `x_args_for_call`: a clone of what was recorded. The second
/// implementation is never called. It is there for the compiler: a parameter whose type
/// cannot be recorded is then reported once, where it is recorded, and not a second time
/// here.
pub trait ArgsByClone<A> {
    fn args_for_call(&self, i: usize, name: &str) -> A;
}

impl<A: Clone, S: ?Sized, R> ArgsByClone<A> for &Method<A, S, R> {
    #[track_caller]
    fn args_for_call(&self, i: usize, name: &str) -> A {
        let inner = self.lock();
        match inner.args_for_call.get(i) {
            Some(args) => args.clone(),
            None => {
                let count = inner.args_for_call.len();
                drop(inner);
                panic!(
                    "{name}_args_for_call({i}): there is no call {i}, the method was called {count} time(s)"
                );
            }
        }
    }
}

pub trait ArgsNotClone<A> {
    fn args_for_call(&self, i: usize, name: &str) -> A;
}

impl<A, S: ?Sized, R> ArgsNotClone<A> for Method<A, S, R> {
    fn args_for_call(&self, _i: usize, name: &str) -> A {
        unreachable!("{name}: what is recorded of the arguments is always `Clone`")
    }
}

/// The zero value of a return type, for a method nothing was set for: `Default::default()`
/// as counterfeiter returns Go's zero value; for a `Result` the `Ok` of that, as Go's zero
/// value of `(T, error)` has a nil error; a panic that says what to do for a type that has
/// neither.
pub struct Zero<R>(PhantomData<fn() -> R>);

impl<R> Zero<R> {
    pub const NEW: Self = Zero(PhantomData);
}

pub trait ZeroByDefault<R> {
    fn zero(&self, name: &str) -> R;
}

impl<R: Default> ZeroByDefault<R> for &&Zero<R> {
    fn zero(&self, _name: &str) -> R {
        R::default()
    }
}

pub trait ZeroByOk<R> {
    fn zero(&self, name: &str) -> R;
}

impl<T: Default, E> ZeroByOk<Result<T, E>> for &Zero<Result<T, E>> {
    fn zero(&self, _name: &str) -> Result<T, E> {
        Ok(T::default())
    }
}

pub trait ZeroByPanic<R> {
    fn zero(&self, name: &str) -> R;
}

impl<R> ZeroByPanic<R> for Zero<R> {
    fn zero(&self, name: &str) -> R {
        let method = name.rsplit("::").next().unwrap_or(name);
        panic!(
            "{name} was called, but the test set no return value for it and `{}` has no default: \
             use {method}_returns(..), {method}_returns_with(..) or {method}_calls(..)",
            type_name::<R>()
        );
    }
}

/// The value a test gave to `x_returns` or `x_returns_on_call`, on its way to a [`Producer`]:
/// a value that is `Clone` is returned as often as the method is called; a `Result` whose
/// `Ok` is `Clone` likewise when it is an `Ok`; any other value once. All of them have to be
/// `Send`, as a fake is shared between threads.
pub struct Given<R>(Cell<Option<R>>);

impl<R> Given<R> {
    pub fn new(value: R) -> Self {
        Given(Cell::new(Some(value)))
    }

    fn take(&self) -> R {
        self.0.take().expect("a given value is taken once")
    }
}

fn locked<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(PoisonError::into_inner)
}

fn once<R: Send + 'static>(value: R, name: &'static str) -> Producer<R> {
    let value = Mutex::new(Some(value));
    Arc::new(move || {
        let value = locked(&value).take();
        value.unwrap_or_else(|| {
            let method = name.rsplit("::").next().unwrap_or(name);
            panic!(
                "{name} was called again, but the value the test set for it is a `{}`, which \
                 is not `Clone` and has been returned already: use {method}_returns_with(|| ..) \
                 to make one for every call",
                type_name::<R>()
            )
        })
    })
}

pub trait GivenClone<R> {
    fn producer(&self, name: &'static str) -> Producer<R>;
}

impl<R: Clone + Send + 'static> GivenClone<R> for &&&Given<R> {
    fn producer(&self, _name: &'static str) -> Producer<R> {
        // In a lock, so that the value does not have to be `Sync`.
        let value = Mutex::new(self.take());
        Arc::new(move || locked(&value).clone())
    }
}

pub trait GivenResult<R> {
    fn producer(&self, name: &'static str) -> Producer<R>;
}

impl<T: Clone + Send + 'static, E: Send + 'static> GivenResult<Result<T, E>>
    for &&Given<Result<T, E>>
{
    fn producer(&self, name: &'static str) -> Producer<Result<T, E>> {
        match self.take() {
            Ok(value) => {
                let value = Mutex::new(value);
                Arc::new(move || Ok(locked(&value).clone()))
            }
            Err(err) => once(Err(err), name),
        }
    }
}

pub trait GivenOnce<R> {
    fn producer(&self, name: &'static str) -> Producer<R>;
}

impl<R: Send + 'static> GivenOnce<R> for &Given<R> {
    fn producer(&self, name: &'static str) -> Producer<R> {
        once(self.take(), name)
    }
}

pub trait GivenNotSend<R> {
    fn producer(&self, name: &'static str) -> Producer<R>;
}

impl<R> GivenNotSend<R> for Given<R> {
    #[track_caller]
    fn producer(&self, name: &'static str) -> Producer<R> {
        let method = name.rsplit("::").next().unwrap_or(name);
        panic!(
            "{name}_returns: a `{}` is not `Send`, so the fake, which is shared between \
             threads, cannot keep it: use {method}_returns_with(|| ..) or {method}_calls(..)",
            type_name::<R>()
        );
    }
}
